}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct LinkView {
    pub id: String,
    /// `rtu`, `tcp`, `rtu_over_tcp`, `simulator`
    pub kind: &'static str,
    pub label: String,
    pub simulated: bool,
    pub state: LinkState,
    pub error: Option<String>,
    pub devices: Vec<DeviceView>,
}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct LiveSnapshot {
    pub ts_ms: i64,
    pub session_id: String,
    pub tags: Vec<TagView>,
    pub links: Vec<LinkView>,
    pub alarms: AlarmSnapshot,
    pub historian_error: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct LiveFrame {
    pub ts_ms: i64,
    pub tags: Vec<TagView>,
    pub points: Vec<TrendPoint>,
    /// Points that could not be delivered (frame cap or bus lag). Never silent.
    pub dropped: u64,
    pub links: Option<Vec<LinkView>>,
    pub alarms: Option<AlarmSnapshot>,
    pub historian_error: Option<String>,
}

impl LiveFrame {
    pub fn is_empty(&self) -> bool {
        self.tags.is_empty()
            && self.points.is_empty()
            && self.dropped == 0
            && self.links.is_none()
            && self.alarms.is_none()
    }
}

#[derive(Clone, Debug, PartialEq, Serialize)]
        lock(&self.shared.links).get(link_id).map(|e| e.config.clone())
    }

    pub fn snapshot(&self) -> LiveSnapshot {
        let now = self.shared.now();
        let links = self.links();
        LiveSnapshot {
            ts_ms: now,
            session_id: self.shared.session_id.clone(),
            tags: lock(&self.shared.live).all(),
            links,
            alarms: lock(&self.shared.alarms).snapshot(now),
            historian_error: lock(&self.shared.historian_error).clone(),
        }
    }

    /// Changes since the last call (the shell calls this at ≤ 4 Hz).
    pub fn take_frame(&self) -> LiveFrame {
        let now = self.shared.now();
        let links_rev = self.shared.links_rev.load(Ordering::SeqCst);
        let alarm_rev = lock(&self.shared.alarms).revision();
        let (send_links, send_alarms) = {
            let mut c = lock(&self.shared.cursor);
            let l = c.links_rev != links_rev;
            let a = c.alarm_rev != alarm_rev;
            c.links_rev = links_rev;
            c.alarm_rev = alarm_rev;
            (l, a)
        };
        let links = send_links.then(|| self.links());
        let (tags, points, dropped) = lock(&self.shared.live).take_changes();
        let alarms = send_alarms.then(|| lock(&self.shared.alarms).snapshot(now));
        LiveFrame {
            ts_ms: now,
            tags,
            points,
            dropped,
            links,
            alarms,
            historian_error: lock(&self.shared.historian_error).clone(),
        }
    }

    /// Link views with fresh counters (heartbeat); counters change without a link revision.
    pub fn link_status(&self) -> Vec<LinkView> {
        self.links()
    }

    // ---- historian ----

    pub fn flush(&self) {
        self.shared.flush_log();
    }

    pub fn sessions(&self) -> Result<Vec<SessionInfo>, SessionError> {
        let h = self
            .shared
            .historian
            .as_ref()
            .ok_or_else(|| SessionError::Historian(self.historian_error_text()))?;
        lock(h).sessions().map_err(|e| SessionError::Historian(e.to_string()))
    }

    fn historian_error_text(&self) -> String {
        lock(&self.shared.historian_error)
            .clone()
            .unwrap_or_else(|| "not opened".into())
    }

    pub fn trend(
        &self,
        device_id: &str,
        tag_id: &str,
        from_ms: i64,
        to_ms: i64,
        buckets: usize,
    ) -> Result<TrendSeries, SessionError> {
        let (d, _, _) = self.find_device(device_id)?;
        self.shared.flush_log();
        let h = self
            .shared
            .historian
            .as_ref()
            .ok_or_else(|| SessionError::Historian(self.historian_error_text()))?;
        let rows = lock(h)
            .samples(&self.shared.session_id, Some(device_id), Some(tag_id), from_ms, to_ms)
            .map_err(|e| SessionError::Historian(e.to_string()))?;
        let input: Vec<TrendInput> = rows
            .iter()
            .map(|s| TrendInput {
                ts_ms: s.ts_ms,
                value: s.value,
                quality: s.quality,
            })
            .collect();
        Ok(trend::decimate(&input, from_ms, to_ms, buckets, d.stale_threshold_ms()))
    }

// The only module that talks to Tauri. No call here carries a frame, an address or a function code:
// control requests name a device, a profile command or register, and an engineering value; the Rust
// command service checks arming, bounds and confirmation and builds the frame (safety rules 2-3).
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import type {
  AuditRow,
  CommandOutcome,
  CommSettingKind,
  ControlStatus,
  Preview,
  ReportData,
  Role,
  Wizard,
  WizardSupport,
  AlarmDef,
  AlarmSnapshot,
  AppInfo,
  DeviceInspection,
  EventRow,
  ExportFormat,
  ExportResult,
  LiveFrame,
  LiveSnapshot,
  PortView,
  ProfileView,
  TrainingFault,
  TrainingStatus,
  TrendSeries,
} from "./types.ts";

export const FRAME_EVENT = "buslink://frame";

export function hasBackend(): boolean {
  return typeof (window as unknown as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__ !== "undefined";
}

/** Error text from a rejected command (Rust returns plain strings). */
export function errorText(e: unknown): string {
  if (typeof e === "string") return e;
  if (e instanceof Error) return e.message;
  return String(e);
}

export interface ConnectReq {
  kind: "rtu" | "tcp" | "rtu_over_tcp";
  port?: string;
  baud?: number;
  data_bits?: number;
  parity?: "none" | "even" | "odd";
  stop_bits?: number;
  host?: string;
  tcp_port?: number;
}

export interface ConnectResult {
  link_id: string;
  isolation_advice: boolean;
  otg_battery_advice: boolean;
  high_baud_warning: boolean;
}

/** What Start polling achieved beyond polling (Android foreground service). */
export interface StartResult {
  android: boolean;
  background: boolean;
  notifications_denied: boolean;
  error: string | null;
}

export const api = {
  appInfo: () => invoke<AppInfo>("app_info"),
  listPorts: () => invoke<PortView[]>("list_ports"),
  listProfiles: () => invoke<ProfileView[]>("list_profiles"),
  connect: (req: ConnectReq) => invoke<ConnectResult>("connect_link", { req }),
  reconnect: (id: string) => invoke<void>("reconnect_link", { id }),
  disconnect: (id: string) => invoke<void>("disconnect_link", { id }),
  removeLink: (id: string) => invoke<void>("remove_link", { id }),
  startPolling: (id: string) => invoke<StartResult>("start_polling", { id }),
  stopPolling: (id: string) => invoke<void>("stop_polling", { id }),
  addDevice: (req: { link_id: string; profile_key: string; unit_id: number; name?: string; poll_interval_ms?: number }) =>
    invoke<string>("add_device", { req }),
  removeDevice: (id: string) => invoke<void>("remove_device", { id }),
  snapshot: () => invoke<LiveSnapshot>("live_snapshot"),
  trend: (req: { device_id: string; tag_id: string; from_ms: number; to_ms: number; buckets: number }) =>
    invoke<TrendSeries>("trend_query", { req }),
  exportSession: (format: ExportFormat) => invoke<ExportResult>("export_session", { format }),
  inspect: (id: string) => invoke<DeviceInspection>("inspect_device", { id }),
  alarms: () => invoke<AlarmSnapshot>("alarm_list"),
  alarmAdd: (def: AlarmDef) => invoke<void>("alarm_add", { def }),
  alarmRemove: (id: string) => invoke<void>("alarm_remove", { id }),
  alarmAck: (id: string) => invoke<void>("alarm_ack", { id }),
  alarmShelve: (id: string, minutes: number) => invoke<void>("alarm_shelve", { req: { id, minutes } }),
  alarmUnshelve: (id: string) => invoke<void>("alarm_unshelve", { id }),
  alarmSetOos: (id: string, out_of_service: boolean) => invoke<void>("alarm_set_oos", { req: { id, out_of_service } }),
  alarmEvents: () => invoke<EventRow[]>("alarm_events"),
  alarmDefaults: (unit: string | null, span: number) =>
    invoke<{ deadband: number; delay_ms: number }>("alarm_defaults", { req: { unit, span } }),
  trainingStatus: () => invoke<TrainingStatus>("training_status"),
  trainingStart: () => invoke<TrainingStatus>("training_start"),
  trainingFault: (unit: number, fault: TrainingFault, seconds: number) =>
    invoke<TrainingStatus>("training_fault", { req: { unit, fault, seconds } }),
  trainingClear: (unit: number) => invoke<TrainingStatus>("training_clear", { unit }),
  // ---- control (simulated devices) and commissioning ----
  controlStatus: () => invoke<ControlStatus>("control_status"),
