#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Verdict {
    Allow,
    Limited { retry_after_s: u64 },
}

#[derive(Debug)]
struct Entry {
    tokens: f64,
    last_ms: i64,
    fails: Vec<i64>,
    locked_until: i64,
