pub const MAX_TREND_SPAN_MS: i64 = 366 * 86_400_000;

#[derive(Clone, Copy)]
pub(crate) struct ClientAddr(pub SocketAddr);

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct ClientInfo {
    pub id: u64,
    pub addr: String,
    pub since_ms: i64,
