            let n = rng.below(80) as usize;
            let s: String = (0..n)
                .map(|_| match rng.below(8) {
                    0 => '/',
                    1 => '#',
                    2 => '+',
                    3 => '$',
                    4 => char::from_u32(rng.below(0x3000) as u32).unwrap_or('x'),
                    5 => ' ',
                    6 => '\0',
                    _ => (b'a' + rng.below(26) as u8) as char,
                })
                .collect();
            let l = sanitize_level(&s);
            assert!(!l.is_empty() && l.len() <= MAX_LEVEL, "{l:?}");
