    fn example_topics() {
        assert_eq!(sample_topic("plant 1", "gw", "soil/1", "temperature"), "buslink/plant_1/gw/soil_1/temperature");
        assert_eq!(status_topic("a", "b"), "buslink/a/b/status");
        assert_eq!(sanitize_level(".."), "_");
    }
}
