                port: 8883,
                tls: true
            }
        );
        assert!(cfg("mqtts://b:8884").validate().is_ok());
        assert!(cfg("mqtt://192.168.1.2").validate().is_err(), "plain text needs the tick");
        let mut c = cfg("mqtt://192.168.1.2");
        c.allow_insecure = true;
        assert_eq!(c.validate().unwrap().port, 1883);
        for bad in [
            "mqtts://user:pw@host",
            "mqtts://user@host",
            "http://host",
            "host:8883",
            "mqtts://",
            "mqtts://ho st",
            "mqtts://host:0",
            "mqtts://host:99999",
            "mqtts://-host",
        ] {
