    if !cfg.username.is_empty() {
        o.set_credentials(cfg.username.clone(), password.map(|p| p.expose().to_string()).unwrap_or_default());
    }
    if will {
        o.set_last_will(LastWill::new(cfg.status_topic(), "offline", QoS::AtLeastOnce, true, None));
    }
