#[derive(Clone, Debug, Serialize)]
pub struct MqttStatus {
    pub state: MqttState,
    pub broker: String,
    pub client_id: String,
    pub outbox_depth: usize,
    pub outbox_max: usize,
    /// Messages stored for publishing.
