    let Some(Rx::Connect { username, password, .. }) = broker.log().into_iter().find(|r| matches!(r, Rx::Connect { .. })) else { panic!() };
    assert_eq!((username.as_deref(), password.as_deref()), (Some("alice"), Some(PW)));
    for (_, _, rx) in broker.data() {
        let Rx::Publish { payload, topic, .. } = rx else { panic!() };
