// DOM helpers. Text always goes through textContent / text nodes: no innerHTML anywhere (ui.md).

type Child = Node | string | number | null | undefined | false;
type Handler = (e: Event) => void;
export type Attrs = Record<string, string | number | boolean | null | undefined | Handler>;

export function h<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs?: Attrs | null,
  ...children: (Child | Child[])[]
): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);
  if (attrs) {
    for (const [k, v] of Object.entries(attrs)) {
      if (v === undefined || v === null || v === false) continue;
      if (k.startsWith("on:") && typeof v === "function") {
        el.addEventListener(k.slice(3), v);
      } else if (typeof v === "function") {
        continue;
      } else if (v === true) {
        el.setAttribute(k, "");
      } else {
        el.setAttribute(k, String(v));
      }
    }
  }
  append(el, ...children);
  return el;
}

export function append(el: Node, ...children: (Child | Child[])[]): void {
  for (const c of children.flat()) {
    if (c === null || c === undefined || c === false) continue;
    el.appendChild(typeof c === "string" || typeof c === "number" ? document.createTextNode(String(c)) : c);
  }
}

export function clear(el: Node): void {
  while (el.firstChild) el.removeChild(el.firstChild);
}

export function setText(el: Element, text: string): void {
  if (el.textContent !== text) el.textContent = text;
}

export function svgShape(kind: "triangle" | "diamond" | "square" | "circle" | "hex", label: string, cls: string): SVGSVGElement {
  const ns = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(ns, "svg");
  svg.setAttribute("viewBox", "0 0 20 20");
  svg.setAttribute("class", `shape ${cls}`);
  svg.setAttribute("aria-hidden", "true");
  const shapeEl =
    kind === "circle"
      ? document.createElementNS(ns, "circle")
      : document.createElementNS(ns, "polygon");
  if (kind === "circle") {
    shapeEl.setAttribute("cx", "10");
    shapeEl.setAttribute("cy", "10");
    shapeEl.setAttribute("r", "8.5");
  } else {
    const pts: Record<string, string> = {
      triangle: "10,1.5 19,18.5 1,18.5",
      diamond: "10,1 19,10 10,19 1,10",
      square: "2,2 18,2 18,18 2,18",
      hex: "5,1.5 15,1.5 19.5,10 15,18.5 5,18.5 0.5,10",
    };
    shapeEl.setAttribute("points", pts[kind] ?? pts.square ?? "");
  }
  svg.appendChild(shapeEl);
  if (label) {
    const text = document.createElementNS(ns, "text");
    text.setAttribute("x", "10");
    text.setAttribute("y", kind === "triangle" ? "15.5" : "14");
    text.setAttribute("text-anchor", "middle");
    text.textContent = label;
    svg.appendChild(text);
  }
  return svg;
}

export function announce(text: string, urgent = false): void {
  const el = document.getElementById(urgent ? "announcer-urgent" : "announcer");
  if (!el) return;
  el.textContent = "";
  window.setTimeout(() => {
    el.textContent = text;
  }, 30);
}
import { h } from "../dom.ts";

export interface View {
  el: HTMLElement;
  destroy?: () => void;
}

/** A status line next to a form or action; text only, announced politely. */
export function statusLine(): { el: HTMLElement; set: (text: string, kind?: "ok" | "error" | "info") => void } {
  const el = h("p", { class: "status-line", role: "status", "aria-live": "polite" });
  return {
    el,
    set(text, kind = "info") {
      el.textContent = text;
      el.dataset.kind = kind;
    },
  };
}

/** Labeled form field with an error slot linked by aria-describedby (WCAG 3.3.1). */
export function field(
  id: string,
  label: string,
  control: HTMLInputElement | HTMLSelectElement,
  hint?: string,
): { el: HTMLElement; error: (text: string | null) => void } {
  control.id = id;
  const err = h("span", { class: "field-error", id: `${id}-err` });
  const hintEl = hint ? h("span", { class: "field-hint", id: `${id}-hint` }, hint) : null;
  control.setAttribute("aria-describedby", [hint ? `${id}-hint` : "", `${id}-err`].filter(Boolean).join(" "));
  const el = h("div", { class: "field" }, h("label", { for: id }, label), control, hintEl, err);
  return {
    el,
    error(text) {
      err.textContent = text ?? "";
      if (text) control.setAttribute("aria-invalid", "true");
      else control.removeAttribute("aria-invalid");
    },
  };
}

export function select(options: [string, string][], value?: string): HTMLSelectElement {
  const s = h("select", null, ...options.map(([v, label]) => h("option", { value: v }, label)));
  if (value !== undefined) s.value = value;
  return s;
}

/**
 * Re-render `container` without losing keyboard focus: elements carry `data-fk`
 * keys, and the focused key is restored after `render` (WCAG 2.4.3 / 2.4.7).
 */
export function preserveFocus(container: HTMLElement, render: () => void): void {
  const active = document.activeElement;
  const key = active instanceof HTMLElement && container.contains(active) ? active.dataset.fk : undefined;
  render();
  if (key) {
    const again = container.querySelector<HTMLElement>(`[data-fk="${CSS.escape(key)}"]`);
    again?.focus();
  }
}
// i18n: every UI string comes from i18n/en.json and i18n/id.json (same keys; checked by scripts/check-i18n.mjs).
import en from "./i18n/en.json";
import id from "./i18n/id.json";
import type { Lang } from "./format.ts";
import type { Text } from "./types.ts";

type Dict = Record<string, string>;
const dicts: Record<Lang, Dict> = { en: en as Dict, id: id as Dict };
const STORAGE_KEY = "buslink.lang";

let current: Lang = detect();
const listeners = new Set<() => void>();

function detect(): Lang {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === "en" || saved === "id") return saved;
  } catch {
    /* storage unavailable: follow the system */
  }
  const nav = (navigator.languages?.[0] ?? navigator.language ?? "en").toLowerCase();
  return nav.startsWith("id") || nav.startsWith("in") ? "id" : "en";
}

export function lang(): Lang {
  return current;
}

export function setLang(l: Lang): void {
  current = l;
  try {
    localStorage.setItem(STORAGE_KEY, l);
  } catch {
    /* not persisted; still switched for this run */
  }
  document.documentElement.lang = l;
  for (const f of listeners) f();
}

export function onLangChange(f: () => void): void {
  listeners.add(f);
}

/** Translate `key`, replacing `{name}` placeholders. A missing key shows the key itself (and fails the build check). */
export function t(key: string, vars?: Record<string, string | number>): string {
  let s = dicts[current][key] ?? dicts.en[key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  }
  return s;
}

