    if (!ifaceSel.value) {
      fIface.error(t("share.err.iface"));
      bad = true;
    }
    if (!Number.isInteger(port) || port < 1024 || port > 65535) {
      fPort.error(t("share.err.port"));
      bad = true;
    }
    if (bad) return;
    startBtn.disabled = true;
    try {
      apply(await api.lanStart(ifaceSel.value, port));
