  function read(): MqttConfig {
    const base = config;
    return {
      broker_url: urlIn.value.trim(),
      site: siteIn.value.trim(),
      gateway: gwIn.value.trim(),
      client_id: idIn.value.trim(),
      username: userIn.value.trim(),
