  }

  function fill(c: MqttConfig, hasPw: boolean, store: string, persistent: boolean) {
    config = c;
    urlIn.value = c.broker_url;
    siteIn.value = c.site;
    gwIn.value = c.gateway;
    idIn.value = c.client_id;
    userIn.value = c.username;
