      status.set(t("mqtt.password.removed"), "ok");
    } catch (err) {
      status.set(errorText(err), "error");
    }
  });
  testBtn.addEventListener("click", async () => {
    testBtn.disabled = true;
    status.set(t("mqtt.testing"));
