  const fp = h("code", { class: "mono" });
  const clientsBox = h("div", { class: "table-wrap" });
  const counters = h("p", { class: "muted small" });
  const stopBtn = h("button", { type: "button", class: "danger", "data-testid": "share-stop" }, t("share.stop"));
